package com.talentsync.applicationservice.controller;
import com.talentsync.applicationservice.dto.*; import com.talentsync.applicationservice.service.ApplicationService; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/applications") public class ApplicationController {private final ApplicationService service; @Value("${jwt.secret}") String secret; public ApplicationController(ApplicationService s){service=s;} private Long user(String auth){try{return ((Number)Jwts.parserBuilder().setSigningKey(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseClaimsJws(auth.substring(7)).getBody().get("userId")).longValue();}catch(Exception e){throw new SecurityException("Valid authentication is required");}} private String role(String a){try{return Jwts.parserBuilder().setSigningKey(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseClaimsJws(a.substring(7)).getBody().get("role",String.class);}catch(Exception e){return "";}}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ResponseEntity<ApplicationResponse> submit(@RequestParam Long jobId,@RequestParam(required=false) String coverLetter,@RequestPart MultipartFile resume,@RequestHeader("Authorization") String auth){if(!"CANDIDATE".equals(role(auth)))throw new SecurityException("Candidates only");return ResponseEntity.status(201).body(service.submit(user(auth),jobId,coverLetter,resume));} @GetMapping("/my-applications") List<ApplicationResponse> mine(@RequestHeader("Authorization") String a){return service.mine(user(a));} @GetMapping("/candidate/{candidateId}") List<ApplicationResponse> byCandidate(@PathVariable Long candidateId,@RequestHeader("Authorization") String a){Long loggedInUser=user(a);if(!candidateId.equals(loggedInUser) && !"RECRUITER".equals(role(a)))throw new SecurityException("Not authorized");return service.mine(candidateId);} @GetMapping("/job/{jobId}") List<ApplicationResponse> job(@PathVariable Long jobId,@RequestHeader("Authorization") String a){if(!"RECRUITER".equals(role(a)))throw new SecurityException("Recruiters only");return service.forJob(jobId);} @PutMapping("/{id}/status") ApplicationResponse status(@PathVariable Long id,@RequestParam com.talentsync.applicationservice.entity.ApplicationStatus status,@RequestHeader("Authorization") String a){if(!"RECRUITER".equals(role(a)))throw new SecurityException("Recruiters only");return service.updateStatus(id,status);} @GetMapping("/{id}") ApplicationResponse get(@PathVariable Long id,@RequestHeader("Authorization") String a){ApplicationResponse r=service.get(id);if(!r.candidateId().equals(user(a))&& !"RECRUITER".equals(role(a)))throw new SecurityException("Not authorized");return r;} @GetMapping("/{id}/resume") ResponseEntity<org.springframework.core.io.Resource> resume(@PathVariable Long id,@RequestHeader("Authorization") String a)throws Exception{ApplicationResponse r=service.get(id);if(!r.candidateId().equals(user(a))&& !"RECRUITER".equals(role(a)))throw new SecurityException("Not authorized");Path p=service.resume(id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+r.resumeFileName()+"\"").body(new org.springframework.core.io.UrlResource(p.toUri()));}}
